steps.fn:
() => {
 const data = JSON.parse(document.body.innerText);
 if (data.success !== 1 || !Array.isArray(data.reviews)) throw new Error('Steam 未返回有效评价，检查应用 ID 或当前页面');
 return {summary: data.query_summary, cursor: data.cursor, reviews: data.reviews.map(r => ({id: r.recommendationid, text: r.review, language: r.language, recommended: r.voted_up, playtimeMinutes: r.author?.playtime_forever, createdAt: r.timestamp_created, updatedAt: r.timestamp_updated, helpfulVotes: r.votes_up, steamPurchase: r.steam_purchase, receivedForFree: r.received_for_free}))};
}
